SELECT P.FAVORITA, P.ID, P.TIPO, P.JEITO, P.TITULO, P.INSTRUCAO, P.SEGUNDO, V.ID VIDEO_ID, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL, (SELECT COUNT(*) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) VEZES, (SELECT MAX(D.DIA) FROM PRATICA_DIARIO D WHERE D.PRATICA_ID = P.ID) ULTIMA FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE P.ID = {{id}}